import { test, expect } from '@playwright/test';

test.describe('Notification Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should navigate to related content when clicking a notification', async ({ page }) => {
    // Trigger a notification (assuming there's a button to create one)
    const notificationTriggerButton = page.getByRole('button', { name: /trigger notification/i });
    await notificationTriggerButton.click();

    // Wait for notification to appear
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Click on the notification to navigate
    await notification.click();

    // Verify navigation occurred by checking URL or page content
    await expect(page).toHaveURL(/.*\/related-content/);

    // Verify the related content is displayed
    const relatedContent = page.getByRole('heading', { name: /related content/i });
    await expect(relatedContent).toBeVisible();
  });

  test('should display correct notification content before navigation', async ({ page }) => {
    // Create a notification with specific content
    const notificationButton = page.getByRole('button', { name: /create notification/i });
    await notificationButton.click();

    // Verify notification contains expected text
    const notification = page.getByRole('alert');
    await expect(notification).toContainText(/new message/i);

    // Verify notification has a clickable element
    const notificationLink = notification.getByRole('button');
    await expect(notificationLink).toBeEnabled();

    // Click and verify navigation
    await notificationLink.click();

    // Verify we're on the correct page
    const pageTitle = page.getByRole('heading', { level: 1 });
    await expect(pageTitle).toBeVisible();
  });

  test('should handle multiple notifications and navigate to correct content', async ({ page }) => {
    // Create first notification
    const createFirstButton = page.getByRole('button', { name: /add first notification/i });
    await createFirstButton.click();

    // Create second notification
    const createSecondButton = page.getByRole('button', { name: /add second notification/i });
    await createSecondButton.click();

    // Get all notifications
    const notifications = page.getByRole('alert');
    const notificationCount = await notifications.count();
    expect(notificationCount).toBeGreaterThanOrEqual(2);

    // Click the second notification
    const secondNotification = notifications.nth(1);
    const secondNotificationText = await secondNotification.textContent();

    await secondNotification.click();

    // Verify navigation to correct content based on notification
    const contentIdentifier = page.getByText(secondNotificationText || '');
    await expect(contentIdentifier).toBeVisible();
  });

  test('should close notification after successful navigation', async ({ page }) => {
    // Trigger notification
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });
    await triggerButton.click();

    // Wait for notification
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Click notification to navigate
    await notification.click();

    // Verify navigation occurred
    await expect(page).toHaveURL(/.*\/related-content/);

    // Verify notification is no longer visible (auto-dismissed after navigation)
    await expect(notification).not.toBeVisible({ timeout: 5000 });
  });

  test('should preserve notification state during navigation', async ({ page }) => {
    // Create notification with specific data
    const notificationButton = page.getByRole('button', { name: /create notification/i });
    await notificationButton.click();

    // Get notification details
    const notification = page.getByRole('alert');
    const notificationId = await notification.getAttribute('data-notification-id');

    // Click to navigate
    await notification.click();

    // Verify we navigated
    await expect(page).toHaveURL(/.*\/related-content/);

    // Verify the related content matches the notification
    const relatedItem = page.getByTestId(`item-${notificationId}`);
    await expect(relatedItem).toBeVisible();
  });
});
